      return `Print "${content[1]}"`;
    }
    return 'Print result';
  }
  
  // Function/Method definitions
  if (/^def\s+(\w+)|^function\s+(\w+)|^static\s+void\s+(\w+)|^void\s+(\w+)/.test(line)) {
    const funcMatch = line.match(/(?:def|function|void)\s+(\w+)\(([^)]*)\)/);
    if (funcMatch) {
      const params = funcMatch[2];
      return params ? `Get input: ${params}` : `Start process`;
    }
    return `Start`;
  }
  
  // Conditional statements - human readable
  if (/^if\s+/.test(line)) {
    let condition = line.replace(/^if\s+/, '').replace(/[:\{].*$/, '').trim();
    
    // Convert to plain English
    if (/\w+\s*%\s*2\s*===?\s*0/.test(condition)) {
      return 'Is number even?';
    } else if (/\w+\s*%\s*2\s*!==?\s*0/.test(condition)) {
      return 'Is number odd?';
    } else if (/(\w+)\s*>\s*(\w+)/.test(condition)) {
      const match = condition.match(/(\w+)\s*>\s*(\w+)/);
      return `Is ${match[1]} > ${match[2]}?`;
    } else if (/(\w+)\s*<\s*(\w+)/.test(condition)) {
      const match = condition.match(/(\w+)\s*<\s*(\w+)/);
      return `Is ${match[1]} < ${match[2]}?`;
    } else if (/(\w+)\s*===?\s*(\w+)/.test(condition)) {
      const match = condition.match(/(\w+)\s*===?\s*(\w+)/);
      return `Is ${match[1]} = ${match[2]}?`;
    }
    
    return `Check condition`;
  }
  
  if (/^elif\s+/.test(line)) {
    return 'Check alternative';
  }
  
  if (/^else[:\{]?/.test(line)) {
    return 'Otherwise';
  }
  
  // Loop statements - simplified
  if (/^for\s+/.test(line)) {
    const rangeMatch = line.match(/range\((\d+)\)/);
    const countMatch = line.match(/i\s*<\s*(\d+)|i\s*<=\s*(\d+)/);
    const count = rangeMatch ? rangeMatch[1] : (countMatch ? (countMatch[1] || countMatch[2]) : 'N');
    return `Repeat ${count} times`;
  }
  
  if (/^while\s+/.test(line)) {
    return `Repeat while true`;
  }
  
  // Return statements
  if (/^return\b/.test(line)) {
    return 'Return result';
  }
  
  // Function calls - simplified
  if (/(\w+)\([^)]*\)/.test(line) && !line.startsWith('if') && !line.startsWith('for') && !line.startsWith('while')) {
    const funcMatch = line.match(/(\w+)\(/);
    if (funcMatch) {
      const funcName = funcMatch[1];
      // Convert function name to readable text
      const readable = funcName.replace(/_/g, ' ');
      return `Process: ${readable}`;
    }
  }
  
  // Variable assignments - describe operation
  if (/(\w+)\s*=\s*/.test(line) && !/===?|!==?/.test(line)) {
    return 'Calculate value';
  }
  
  // Default
  return 'Process step';
}

export function parseToGraph(code) {
  const lines = code
    .split("\n")
    .map((l, index) => ({ text: l.trim(), lineNumber: index + 1, indent: l.search(/\S/) }))
    .filter(l => l.text.length && !l.text.startsWith("#") && !l.text.startsWith("//") && !l.text.startsWith("import") && !l.text.startsWith("using"));

  let nodes = [];
  let edges = [];
  let id = 1;
  
  // Detect language
  let language = 'python';
  if (/function\s+\w+|console\.log|let\s+|const\s+/.test(code)) language = 'javascript';
  else if (/System\.out\.println|public\s+static/.test(code)) language = 'java';
  else if (/#include|printf|cout/.test(code)) language = 'c';
  else if (/SELECT|FROM|WHERE|INSERT|UPDATE|DELETE/i.test(code)) language = 'sql';
  else if (/<html|<head|<body|<div|<style/i.test(code)) language = 'html';

  // Special handling for SQL
  if (language === 'sql') {
    return parseSQLToGraph(code);
  }

  // Special handling for HTML/CSS
  if (language === 'html') {
    return parseHTMLToGraph(code);
  }

  // Add Start node
  nodes.push({ 
    id: id++, 
    text: 'Start', 
    type: 'start',
    shape: 'terminal',
    lineNumber: 1
  });

  let prev = nodes[0];
  let contextStack = []; // Track nested structures (if/else/for/while)
  let loopContext = null;
  let mergePoints = new Map(); // Track where branches merge

  for (let i = 0; i < lines.length; i++) {
    const lineObj = lines[i];
    const line = lineObj.text;
    const lineNumber = lineObj.lineNumber;
    const indent = lineObj.indent;
    let currentType = "process";
    let node = null;
    let shape = "rectangle";

    // Skip closing braces and other syntax
    if (/^[\}\)]/.test(line) || line === '') continue;

    // Pop contexts based on indentation (for Python)
    if (language === 'python') {
      while (contextStack.length > 0 && indent <= contextStack[contextStack.length - 1].indent) {
        const popped = contextStack.pop();
        
        // Create merge point for if-else structures
        if (popped.type === 'decision' || popped.type === 'else') {
          if (!mergePoints.has(popped.mergeId)) {
            const mergeNode = { id: id++, text: 'Continue', type: 'merge', shape: 'circle', lineNumber: lineNumber };
            nodes.push(mergeNode);
            mergePoints.set(popped.mergeId, mergeNode);
            
            // Connect previous nodes to merge point
            if (popped.trueBranch) {
              edges.push({ from: popped.trueBranch.id, to: mergeNode.id });
            }
            if (popped.falseBranch) {
              edges.push({ from: popped.falseBranch.id, to: mergeNode.id });
            }
            prev = mergeNode;
          }
        }
        
        // Handle loop back edges
        if (popped.type === 'loop') {
          if (prev && prev !== popped.node) {
            edges.push({ from: prev.id, to: popped.node.id, label: "Loop back" });
          }
          loopContext = null;
          prev = popped.node;
        }
      }
    }

    // Detect key structures
    if (/^(def|function|void|static\s+void)\s+/.test(line)) {
      // Function declaration - convert to input parameter
      const funcMatch = line.match(/\(([^)]+)\)/);
      if (funcMatch && funcMatch[1].trim()) {
        const params = funcMatch[1].trim();
        currentType = "input";
        shape = "parallelogram";
        const algorithmText = `Get input: ${params}`;
        node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
        nodes.push(node);
        edges.push({ from: prev.id, to: node.id });
        prev = node;
      }
      continue;
      
    } else if (/^if\s+/.test(line)) {
      currentType = "decision";
      shape = "diamond";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      edges.push({ from: prev.id, to: node.id });
      
      const mergeId = `merge_${id}`;
      contextStack.push({ 
        type: 'decision', 
        node: node, 
        indent: indent,
        mergeId: mergeId,
        trueBranch: null,
        falseBranch: null
      });
      prev = node;
      
    } else if (/^elif\s+/.test(line)) {
      currentType = "decision";
      shape = "diamond";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      
      // Connect from previous if/elif's "No" path
      if (contextStack.length > 0) {
        const lastContext = contextStack[contextStack.length - 1];
        edges.push({ from: lastContext.node.id, to: node.id, label: "No" });
        lastContext.falseBranch = node;
        
        // Update context
        contextStack.push({ 
          type: 'decision', 
          node: node, 
          indent: indent,
          mergeId: lastContext.mergeId,
          trueBranch: null,
          falseBranch: null
        });
      }
      prev = node;
      
    } else if (/^else[:\{]?$/.test(line)) {
      if (contextStack.length > 0) {
        const lastContext = contextStack[contextStack.length - 1];
        contextStack.push({ 
          type: 'else', 
          node: lastContext.node, 
          indent: indent,
          mergeId: lastContext.mergeId
        });
      }
      continue;
      
    } else if (/^(for|while)\s+/.test(line)) {
      currentType = "loop";
      shape = "diamond";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      edges.push({ from: prev.id, to: node.id });
      
      loopContext = { node: node, firstInLoop: null };
      contextStack.push({ type: 'loop', node: node, indent: indent });
      prev = node;
      
    } else if (/print\(|console\.log\(|System\.out\.println\(|printf\(|cout/.test(line)) {
      currentType = "output";
      shape = "parallelogram";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      
      // Determine edge label based on context
      let edgeLabel = "";
      if (contextStack.length > 0) {
        const lastContext = contextStack[contextStack.length - 1];
        if (lastContext.type === 'decision' && !lastContext.trueBranch) {
          edgeLabel = "Yes";
          lastContext.trueBranch = node;
        } else if (lastContext.type === 'else' && !lastContext.falseBranch) {
          edgeLabel = "No";
          lastContext.falseBranch = node;
        } else if (lastContext.type === 'loop' && !loopContext.firstInLoop) {
          edgeLabel = "Yes";
          loopContext.firstInLoop = node;
        }
      }
      
      edges.push({ from: prev.id, to: node.id, label: edgeLabel });
      prev = node;
      
    } else if (/(\w+)\([^)]*\)/.test(line) && !line.startsWith('if') && !line.startsWith('for') && !line.startsWith('while')) {
      currentType = "process";
      shape = "rectangle";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      
      // Determine edge label based on context
      let edgeLabel = "";
      if (loopContext && !loopContext.firstInLoop) {
        edgeLabel = "Yes";
        loopContext.firstInLoop = node;
      } else if (contextStack.length > 0) {
        const lastContext = contextStack[contextStack.length - 1];
        if (lastContext.type === 'decision' && !lastContext.trueBranch) {
          edgeLabel = "Yes";
          lastContext.trueBranch = node;
        } else if (lastContext.type === 'else' && !lastContext.falseBranch) {
          edgeLabel = "No";
          lastContext.falseBranch = node;
        }
      }
      
      edges.push({ from: prev.id, to: node.id, label: edgeLabel });
      prev = node;
      
    } else if (/^return\b/.test(line)) {
      currentType = "output";
      shape = "parallelogram";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      edges.push({ from: prev.id, to: node.id });
      prev = node;
      
    } else if (/(\w+)\s*=\s*/.test(line) && !/===?|!==?/.test(line)) {
      // Variable assignment
      currentType = "process";
      shape = "rectangle";
      const algorithmText = codeToAlgorithm(line, language);
      node = { id: id++, text: algorithmText, type: currentType, shape: shape, lineNumber: lineNumber };
      nodes.push(node);
      
      let edgeLabel = "";
      if (contextStack.length > 0) {
        const lastContext = contextStack[contextStack.length - 1];
        if (lastContext.type === 'decision' && !lastContext.trueBranch) {
          edgeLabel = "Yes";
          lastContext.trueBranch = node;
        } else if (lastContext.type === 'else' && !lastContext.falseBranch) {
          edgeLabel = "No";
          lastContext.falseBranch = node;
        } else if (lastContext.type === 'loop' && !loopContext?.firstInLoop) {
          edgeLabel = "Yes";
          if (loopContext) loopContext.firstInLoop = node;
        }
      }
      
      edges.push({ from: prev.id, to: node.id, label: edgeLabel });
      prev = node;
    }
  }

  // Clean up remaining contexts
  while (contextStack.length > 0) {
    const popped = contextStack.pop();
    
    if (popped.type === 'loop' && popped.node) {
      if (prev && prev !== popped.node) {
        edges.push({ from: prev.id, to: popped.node.id, label: "Loop back" });
      }
      // Exit loop
      prev = popped.node;
    }
  }

  // Add End node
  const endNode = { 
    id: id++, 
    text: 'End', 
    type: 'end',
    shape: 'terminal',
    lineNumber: lines.length
  };
  nodes.push(endNode);
  
  // Connect last node to end, handling loop exits
  if (loopContext && loopContext.node) {
    edges.push({ from: loopContext.node.id, to: endNode.id, label: "No" });
  } else if (prev) {
    edges.push({ from: prev.id, to: endNode.id });
  }

  return { nodes, edges };
}

function parseSQLToGraph(code) {
  const nodes = [];
  const edges = [];
  let id = 1;

  // Start
  nodes.push({
    id: id++,
    text: 'Start',
    type: 'start',
    shape: 'terminal',
    lineNumber: 1
  });

  let prev = nodes[0];

  // Parse SELECT statement
  if (/SELECT/i.test(code)) {
    const selectMatch = code.match(/SELECT\s+(.+?)\s+FROM/is);
    const columns = selectMatch ? selectMatch[1].trim() : '*';
    
    const node = {
      id: id++,
      text: `Select columns: ${columns}`,
      type: 'input',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse FROM clause
  if (/FROM/i.test(code)) {
    const fromMatch = code.match(/FROM\s+(\w+)/i);
    const table = fromMatch ? fromMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `From table: ${table}`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse WHERE clause
  if (/WHERE/i.test(code)) {
    const whereMatch = code.match(/WHERE\s+(.+?)(?:;|$)/is);
    const condition = whereMatch ? whereMatch[1].trim().replace(/;/g, '') : 'condition';
    
    const node = {
      id: id++,
      text: `Filter: ${condition}`,
      type: 'decision',
      shape: 'diamond',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse INSERT
  if (/INSERT/i.test(code)) {
    const insertMatch = code.match(/INSERT\s+INTO\s+(\w+)/i);
    const table = insertMatch ? insertMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `Insert into: ${table}`,
      type: 'output',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse UPDATE
  if (/UPDATE/i.test(code)) {
    const updateMatch = code.match(/UPDATE\s+(\w+)/i);
    const table = updateMatch ? updateMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `Update table: ${table}`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse DELETE
  if (/DELETE/i.test(code)) {
    const deleteMatch = code.match(/DELETE\s+FROM\s+(\w+)/i);
    const table = deleteMatch ? deleteMatch[1] : 'table';
    
    const node = {
      id: id++,
      text: `Delete from: ${table}`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }  // Result
  const resultNode = {
    id: id++,
    text: 'Return results',
    type: 'output',
    shape: 'parallelogram',
    lineNumber: 1
  };
  nodes.push(resultNode);
  edges.push({ from: prev.id, to: resultNode.id });

  // End
  const endNode = { 
    id: id++, 
    text: 'End', 
    type: 'end',
    shape: 'terminal',
    lineNumber: 1
  };
  nodes.push(endNode);
  edges.push({ from: resultNode.id, to: endNode.id });

  return { nodes, edges };
}

function parseHTMLToGraph(code) {
  const nodes = [];
  const edges = [];
  let id = 1;

  // Start
  nodes.push({ 
    id: id++, 
    text: 'Start', 
    type: 'start',
    shape: 'terminal',
    lineNumber: 1
  });

  let prev = nodes[0];

  // Parse HTML structure
  if (/<html/i.test(code)) {
    const node = {
      id: id++,
      text: 'Create HTML document',
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse head section
  if (/<head/i.test(code)) {
    const titleMatch = code.match(/<title>(.+?)<\/title>/i);
    const title = titleMatch ? titleMatch[1] : 'Document';
    
    const node = {
      id: id++,
      text: `Set title: "${title}"`,
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse body section
  if (/<body/i.test(code)) {
    const node = {
      id: id++,
      text: 'Create body content',
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse headings
  const h1Match = code.match(/<h1[^>]*>(.+?)<\/h1>/i);
  if (h1Match) {
    const node = {
      id: id++,
      text: `Display heading: "${h1Match[1]}"`,
      type: 'output',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse paragraphs
  const pMatches = code.match(/<p[^>]*>(.+?)<\/p>/gi);
  if (pMatches && pMatches.length > 0) {
    const node = {
      id: id++,
      text: `Display ${pMatches.length} paragraph(s)`,
      type: 'output',
      shape: 'parallelogram',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Parse styles
  if (/<style/i.test(code) || /style=/i.test(code)) {
    const node = {
      id: id++,
      text: 'Apply CSS styling',
      type: 'process',
      shape: 'rectangle',
      lineNumber: 1
    };
    nodes.push(node);
    edges.push({ from: prev.id, to: node.id });
    prev = node;
  }

  // Render output
  const renderNode = {
    id: id++,
    text: 'Render webpage',
    type: 'output',
    shape: 'parallelogram',
    lineNumber: 1
  };
  nodes.push(renderNode);
  edges.push({ from: prev.id, to: renderNode.id });

  // End
  const endNode = { 
    id: id++, 
    text: 'End', 
    type: 'end',
    shape: 'terminal',
    lineNumber: 1
  };
  nodes.push(endNode);
  edges.push({ from: renderNode.id, to: endNode.id });

  return { nodes, edges };
}

